import {section,table,cite,topic,mountTopic} from './topic-tools.js';
import {texEq as eq,inlineMath as m} from './math.js';
import {traceLab,mountTrace,cells} from './array-patterns-tools.js';
import {normalize,activation,activationNames,depthMix,outputMixture,reversibleFrames} from './transformers-model.js';
export const transformersMeta={slug:'models/transformers',title:'Transformer Architecture',description:'Follow the residual stream through attention, gated feedforward layers, normalization, depth retrieval and the vocabulary head; connect shape, expressivity and activation memory.',date:'2024-09-27',updated:'2026-10-14',topicPath:['models'],tags:['transformer','residual','LayerNorm','RMSNorm','SwiGLU','Attention Residuals','softmax bottleneck','embedding tying','reversible'],learningGoals:['Track the tensor shapes and training targets of a causal decoder.','Separate normalization axes, residual placement and initialization.','Explain depth retrieval, output rank and reversible activation storage.'],related:['models/attention','models/position','models/moe','training/objectives','training/parallelism'],prototype:true,visibility:'public',kind:'dense-topic'};
export const transformersAliases=["ai/architectures/transformers/lets-build-gpt-from-scratch","ai/architectures/transformers/residual-normalization-and-initialization","ai/foundations/activation-functions","ai/foundations/batch-normalization","ai/foundations/layer-normalization","ai/foundations/root-mean-square-layer-normalization","ai/foundations/stop-gradients","ai/architectures/general/reversible-networks","ai/architectures/transformers/embedding-tying-in-small-llms","ai/architectures/transformers/attention-residuals","ai/foundations/softmax-bottleneck","ai/training/scaling/transformer-scaling-rules"];
export const transformersSections=[['block','From token IDs to a next-token distribution'],['residual','Why keep an identity path?'],['normalization','Choose which statistics to share'],['normalization-lab','Centering and scaling are different operations'],['placement','Pre-Norm and Post-Norm change the gradient path'],['initialization','Keep depth and width scales separate'],['activations','What does an activation change?'],['gates','From an activation to a gated feedforward layer'],['depth','A residual stream also mixes information across depth'],['depth-lab','Read a source, not just the accumulated sum'],['block-attnres','Compress history into block summaries'],['attnres-systems','Make depth retrieval practical'],['attnres-evidence','What the Attention Residuals experiments establish'],['head','One state, many vocabulary decisions'],['tying','Sharing embeddings changes the parameter budget'],['rank','Why softmax cannot recover every distinction'],['mixtures','Mix distributions after normalization'],['head-evidence','Separate algebraic rank from useful probability error'],['stop-gradient','A gradient boundary is not a teacher update'],['reversible','Reconstruct activations instead of storing every layer'],['budget','Count the actual architecture'],['budget-design','Turn a budget into testable designs'],['checks','Checks before scaling the model'],['sources','Sources and connected notes']];
const formulaTable=(...args)=>table(...args).replace('<table>','<table style="min-width:560px">');
const vector=xs=>'['+xs.map(x=>x.toFixed(3)).join(', ')+']';
function normBody(offset){const x=[-3,-1,1,3].map(v=>v+offset),ln=normalize(x),rms=normalize(x,'rms');return `<p>Use ${m(String.raw`\varepsilon=10^{-5},\ \gamma=1,\ \beta=0`)}.</p>${table('One token, four features',['Quantity','LayerNorm','RMSNorm'],[['Input',vector(x),vector(x)],['Subtracted mean',ln.mean.toFixed(3),'0'],['Divisor',ln.scale.toFixed(3),rms.scale.toFixed(3)],['Output',vector(ln.values),vector(rms.values)]])}<p>Offset ${offset}: LayerNorm removes a common shift. RMSNorm retains the direction of the shifted vector while controlling its root mean square. Neither operation mixes tokens.</p>`;}
function curve(name,x){const px=v=>40+(v+4)*50,py=v=>200-v*35,path=Array.from({length:161},(_,i)=>{const v=-4+i/20;return `${i?'L':'M'}${px(v).toFixed(2)},${py(activation(name,v)).toFixed(2)}`;}).join(' '),y=activation(name,x);return `<svg viewBox="0 0 470 370" role="img" aria-label="${name} plotted for x from minus four to four; current input ${x}, output ${y.toFixed(4)}"><path d="M40 200H440 M240 35V340" fill="none" stroke="#93748a"/><path d="${path}" fill="none" stroke="#bad6fa" stroke-width="3"/><path d="M${px(x)} 200V${py(y)}" stroke="#bd738e" stroke-dasharray="4 4"/><circle cx="${px(x)}" cy="${py(y)}" r="5" fill="#bd738e"/><text x="10" y="65">4</text><text x="10" y="135">2</text><text x="5" y="275">−2</text><text x="5" y="345">−4</text><text x="40" y="225">−4</text><text x="245" y="225">0</text><text x="430" y="225">4</text><text x="420" y="190">x</text><text x="250" y="42">f(x)</text><text x="30" y="360">x=${x.toFixed(2)} → ${y.toFixed(4)}</text></svg><p>The plot uses one common scale: x∈[−4,4], vertical units unchanged between functions. Leaky slope is 0.1; Swish uses β=1. GELU uses the stated tanh approximation, not the exact normal CDF.</p>`;}
function depthBody(choice){const queries=[[0,0],[2,0],[0,2],[-2,0],[0,-2]],f=depthMix(queries[choice]);return `${table('Four separately stored illustrative sources; scores use RMS-normalized keys',['Source value','Score','Weight'],[[1,0],[0,1],[-1,0],[0,-1]].map((v,i)=>[vector(v),f.scores[i].toFixed(3),f.weights[i].toFixed(4)]))}<p>Layer pseudo-query w=${vector(queries[choice])}. Weighted read=${vector(f.values)}. The ordinary sum is always [0,0]; separate sources still contain distinguishable directions.</p><p>Weights sum to 1. Values stay unnormalized. This synthetic two-dimensional example changes the learned query between cases; it does not simulate training. In a trained layer, the query stays fixed and token-dependent sources change.</p>`;}
function mixtureBody(pi){const f=outputMixture(pi);return `${table('Shared output embeddings w=[−1,0,1]; component states −2 and +2',['Token','Component −2','Component +2','Mix states → softmax','Softmax → mix'],f.a.map((p,i)=>[String(i),p.toFixed(4),f.b[i].toFixed(4),f.context[i].toFixed(4),f.probability[i].toFixed(4)]))}<p>Weight on component −2: ${pi.toFixed(2)}. At π=0.5, mixing states gives h=0 and probabilities [1/3,1/3,1/3]. Mixing distributions gives approximately [0.4413,0.1173,0.4413]. Two plausible extremes need not make the middle token equally plausible.</p><p>One context demonstrates operation order, not matrix rank. The multi-context rank argument is given above.</p>`;}
function revBody(f){return `<h4>${f.title}</h4>${cells([f.x1,f.x2,f.y1,f.y2])}<p>Cell order: x₁, x₂, y₁, y₂. A dash means not yet computed or not needed in that reconstruction step.</p><p>${f.explanation}</p>`;}
export function transformersReader(link){return topic(transformersMeta,transformersSections,'Understand what each block reads, what it writes and what the output head can express.',`
<p>A Transformer repeatedly updates a vector for each token. Attention combines information from accessible positions. A feedforward network transforms each token separately. Residual connections keep an accumulated state between these operations.</p><p>These parts solve different problems. Normalization controls input statistics. Initialization sets the initial scale. An output head turns the final state into token probabilities. Changing one part does not automatically fix a limitation in another.</p>
${section('block','From token IDs to a next-token distribution',`<p>Let B be batch size, T sequence length, d hidden width and V vocabulary size. An embedding lookup maps integer IDs of shape (B,T) to vectors of shape (B,T,d). A bigram table predicts from the current token alone. Contextual attention lets the model use a longer prefix.</p><figure class="transformer-flow"><ol><li><b>Embed</b><span>(B,T) IDs → (B,T,d) states</span></li><li><b>Normalize → causal attention → add</b><span>Read prefix positions; write a d-vector</span></li><li><b>Normalize → feedforward → add</b><span>Transform each token; write a d-vector</span></li><li><b>Repeat blocks → final normalization</b><span>Preserve the residual width</span></li><li><b>Vocabulary projection</b><span>(B,T,d) → (B,T,V) logits</span></li></ol><figcaption>Common decoder-only Pre-Norm anatomy, not a universal Transformer specification. Skip additions carry the incoming state around each sublayer.</figcaption></figure><p>In a conventional head, Q,K,V have per-head width p. Attention computes ${m(String.raw`\operatorname{softmax}\left(\frac{QK^\top}{\sqrt p}+M\right)V`)}. The additive mask ${m(String.raw`M`)} excludes future keys before softmax. Concatenated head outputs are projected back to d. GQA and MLA change the key/value representation; see <a href="${link('models/attention')}">Attention →</a>.</p><p>Training shifts the target by one token. For [A,B,C,D], input [A,B,C] predicts [B,C,D]. All three positions can be trained together because the causal mask prevents target leakage. Generation appends one sampled token and repeats; a KV cache avoids recomputing earlier keys and values.</p><pre><code># Shape pseudocode; attention applies the causal mask internally.
x = embedding(ids)                    # B,T,d
for block in blocks:
    x = x + block.attention(block.norm1(x))
    x = x + block.ffn(block.norm2(x))
logits = final_norm(x) @ output_weight.T  # B,T,V
loss = cross_entropy(logits, next_token_targets)
</code></pre><p>Without positional information, unrestricted self-attention is permutation-equivariant: permuting inputs permutes outputs. A causal mask already breaks unrestricted permutation symmetry. Position mechanisms add explicit order or relative-distance structure; see <a href="${link('models/position')}">Positional Encodings →</a>. Equivariance is not the same as invariance.</p>`)}
${section('residual','Why keep an identity path?',`${eq(String.raw`\begin{aligned}x_{\ell+1}&=x_\ell+F_\ell(x_\ell)\\\frac{\partial x_{\ell+1}}{\partial x_\ell}&=I+J_{F_\ell}\end{aligned}`,'Fₗ produces a same-shaped update. The identity term supplies a direct derivative path.')}<p>Without skips, backpropagation multiplies sublayer Jacobians. Many contractions can shrink gradients; many expansions can increase them. With a residual, a layer can start near the identity instead of learning that identity through every weight matrix.</p><p>The identity term helps but does not guarantee stable gradients. Products of I+J can still contract or expand. A branch can cancel a direction. Initialization, normalization, optimizer settings and depth remain coupled.</p><p>Unrolling gives ${m(String.raw`x_L=x_0+\sum_{\ell=0}^{L-1}F_\ell(x_\ell)`)}. This is an exact sum of the actual updates, not a sum of independent random variables. A state can grow while each normalized branch input remains bounded.</p>`)}
${section('normalization','Choose which statistics to share',`<p>Before choosing a normalization method, specify the axes. BatchNorm (2015) shares feature statistics across examples. LayerNorm (2016) computes statistics within one example. In a Transformer, LayerNorm usually operates over one token's d features. RMSNorm (2019) keeps the same token-local axis but omits centering.</p>${eq(String.raw`\begin{aligned}\mu&=\frac1d\sum_i x_i,&\sigma^2&=\frac1d\sum_i(x_i-\mu)^2\\\operatorname{LN}(x)_i&=\gamma_i\frac{x_i-\mu}{\sqrt{\sigma^2+\varepsilon}}+\beta_i\\\operatorname{RMSNorm}(x)_i&=\gamma_i\frac{x_i}{\sqrt{\frac1d\sum_jx_j^2+\varepsilon}}\end{aligned}`,'d is a positive feature count and ε>0. γ is learned gain; β is learned bias where present; ε protects division. RMSNorm commonly omits β.')}<p>BatchNorm uses the corresponding batch mean and variance per feature, then applies gain and bias. In a CNN, its reduction often also includes spatial positions. Training generally updates running statistics; inference uses those stored statistics. Forward variance and running-variance estimators can differ by implementation.</p>${eq(String.raw`\begin{aligned}\mu_f&=\frac1B\sum_{b=1}^B x_{b,f},\qquad \sigma_f^2=\frac1B\sum_{b=1}^B(x_{b,f}-\mu_f)^2\\y_{b,f}&=\gamma_f\frac{x_{b,f}-\mu_f}{\sqrt{\sigma_f^2+\varepsilon}}+\beta_f\end{aligned}`,"BatchNorm training formula for B examples and feature f. Reduce across the batch, not across token features as in LayerNorm. Uses the biased forward variance; running estimates are separate.")}
<p>The original BatchNorm motivation was to reduce changes in layer-input distributions during training. Later work studied smoother optimization landscapes as an explanation of its benefits. These are explanations to test, not guarantees for every model. ${cite("https://arxiv.org/abs/1805.11604","BatchNorm and optimization smoothness")}</p>
<p>Small batches can make BatchNorm statistics noisy. Synchronizing them across workers adds communication. Pooling sequence positions requires careful masking and causality. This is not proof that BatchNorm cannot work in language models.</p><p>LayerNorm and RMSNorm do not depend on other batch examples for their statistics. Their identical train/test normalization rules do not mean the whole network is context-independent. Attention still couples token representations.</p><p>“Internal covariate shift” was BatchNorm's original motivation, not a settled explanation of all its benefits. Avoid assuming a normalization change always permits a higher learning rate. RMSNorm's paper reports model-dependent running-time reductions of 7–64%; that is not a guaranteed modern-kernel or end-to-end speedup. ${cite('https://arxiv.org/abs/1910.07467','RMSNorm report')}</p>`)}
${section('normalization-lab','Centering and scaling are different operations',`<p>Take one vector and add the same offset to every feature. LayerNorm discards that offset. RMSNorm does not. Both methods divide by a statistic computed from all four features.</p><div class="topic-scene" data-norm-lab><h3>One shared offset</h3><label>Offset <input type="range" min="-4" max="4" step="1" value="0" aria-label="Normalization offset"></label><div data-body>${normBody(0)}</div></div><p>Positive common rescaling approximately cancels in both methods, subject to ε. Common shifts cancel only in LayerNorm. Learned gain and bias can change the normalized mean and variance afterward. For a constant vector, LayerNorm produces zero before its affine transform; RMSNorm can retain a nonzero constant direction.</p><p>These operations couple feature derivatives. For normalized outputs before learned gain and bias, define s and r as the corresponding divisors.</p>
${eq(String.raw`\begin{aligned}s&=\sqrt{\sigma^2+\varepsilon},\qquad r=\sqrt{\frac1d\sum_k x_k^2+\varepsilon}\\\frac{\partial u_i^{\mathrm{LN}}}{\partial x_j}&=\frac{\delta_{ij}-1/d}{s}-\frac{(x_i-\mu)(x_j-\mu)}{d\,s^3}\\\frac{\partial u_i^{\mathrm{RMS}}}{\partial x_j}&=\frac{\delta_{ij}}r-\frac{x_i x_j}{d\,r^3}\\\frac{\partial\tanh(a x_i)}{\partial x_j}&=\delta_{ij}\,a\big[1-\tanh^2(a x_i)\big]\end{aligned}`,"δij is one for i=j and zero otherwise. LayerNorm and RMSNorm couple features; the bare elementwise tanh map has a diagonal Jacobian. Learned affine gains multiply the corresponding output rows.")}
<p>Replacing normalization therefore changes optimization, not only runtime. A trainable tanh scale can control saturation without recreating coordinate coupling.</p>`)}
${section('placement','Pre-Norm and Post-Norm change the gradient path',`${formulaTable('Same normalization family, different placement',['Layout','One sublayer','Implication'],[['Pre-Norm',m(String.raw`x+F(\operatorname{Norm}(x))`),'Unnormalized skip retains a direct identity derivative'],['Post-Norm',m(String.raw`\operatorname{Norm}(x+F(x))`),'Normalization sits on the main gradient path'],['Final norm',m(String.raw`\operatorname{Norm}(x_L)`)+' before head','Controls final read; does not normalize every earlier skip']])}<p>Pre-Norm controls what the branch reads, not the magnitude of the accumulated state. As that state grows, a similarly sized update can become a smaller relative change. This can reduce effective depth in some regimes. Post-Norm controls the resulting state's scale but changes backward propagation.</p><p>Neither is universally stronger or more stable. DeepNorm couples a modified Post-Norm skip with initialization. Its form is ${m(String.raw`\operatorname{LN}(\alpha x+F(x))`)}, not simply a small branch multiplier. For an M-block decoder-only configuration, the report uses ${m(String.raw`\alpha=(2M)^{1/4}`)} and selected Xavier gains ${m(String.raw`\beta=(8M)^{-1/4}`)}; Q/K gains remain 1. Do not transplant this recipe into a different block without checking its derivation. ${cite('https://arxiv.org/pdf/2203.00555','DeepNet Figure 2')}</p>`)}
${section('initialization','Keep depth and width scales separate',`<p>Suppose a linear projection sums d independent unit-variance inputs with independent zero-mean weights. Weight variance ${m(String.raw`\frac1d`)} keeps each output variance near 1. This is a width calculation. Nonlinearities, weight sharing and correlated inputs change its assumptions.</p>${eq(String.raw`\mathbb E\left\|\sum_{\ell=1}^L\Delta_\ell\right\|_2^2=L\sigma^2,\qquad\sqrt{\mathbb E\left\|\sum_\ell\Delta_\ell\right\|_2^2}=\sigma\sqrt L`,'Assumes zero-mean, uncorrelated updates with equal expected squared norm σ². Perfectly aligned updates can instead have norm proportional to L; cross terms determine accumulation.')}<p>A branch multiplier of order ${m(String.raw`\frac1{\sqrt L}`)} controls accumulated energy under the uncorrelated model. Coherent accumulation calls for a different analysis. This generic scaling argument is not the DeepNorm formula.</p><p>BERT-style 0.02 initialization is a model recipe, not a universal width law. At ${m(String.raw`d=768`)}, ${m(String.raw`\frac1{\sqrt d}\approx0.036`)}. This numerical comparison alone does not explain why a particular training run succeeds. Biases, nonlinearities, normalization placement and warmup matter.</p><p>Likewise, ${m(String.raw`\sqrt p`)} attention scaling follows from a specific independent-coordinate dot-product variance calculation. Real queries and keys can be correlated. The derivation and its limits belong in <a href="${link('models/attention')}">Attention →</a>.</p>`)}
${section('activations','What does an activation change?',`<p>Composing only affine layers remains affine. A nonlinearity lets a feedforward branch build a richer token-wise transformation. Its value and derivative shape which signals and gradients pass through.</p>${formulaTable('Scalar activations; x is a preactivation. On narrow screens, scroll horizontally',['Function','Definition','Main distinction'],[['ReLU',m(String.raw`\max(0,x)`),'Negative branch has zero derivative'],['Leaky ReLU',m(String.raw`\begin{cases}x&x\ge0\\ax&x<0\end{cases}`),'Small positive a keeps a negative slope'],['Sigmoid',m(String.raw`\sigma(x)=\dfrac1{1+e^{-x}}`),'Bounded 0–1; derivative σ(1−σ) saturates'],['Tanh',m(String.raw`\tanh(x)`),'Bounded −1–1; derivative 1−tanh² saturates'],['GELU',m(String.raw`x\Phi(x)`),'Smooth probabilistic gate; Φ is normal CDF'],['Swish / SiLU',m(String.raw`x\sigma(\beta x)`)+'; SiLU uses '+m(String.raw`\beta=1`),'Smooth gate with a non-monotone negative region'],['Hardtanh',m(String.raw`\operatorname{clamp}(x,-1,1)`),'Slope 1 inside; 0 outside; endpoints nondifferentiable']])}${eq(String.raw`\begin{aligned}\operatorname{Hardtanh}_{a,b}(x)&=\begin{cases}a&x<a\\x&a\le x\le b\\b&x>b\end{cases}\\\frac{d}{dx}\operatorname{Hardtanh}_{a,b}(x)&=\begin{cases}1&a<x<b\\0&x<a\ \text{or}\ x>b\end{cases}\end{aligned}`,"a&lt;b are fixed clipping bounds; defaults are −1 and 1. The mathematical derivative is undefined at a and b. A framework chooses a backward convention there.")}
<p>A ReLU unit can receive zero branch gradients when its preactivations remain negative. This “dying ReLU” state is not necessarily permanent: upstream changes can move its inputs. Leaky ReLU changes that local derivative; it does not guarantee global optimization success.</p><p>Sigmoid and tanh still serve as output links and gates. Saturating tails do not make them obsolete. A sigmoid output maps one logit to a binary-class probability; stable training uses a logits-based loss. <a href="${link('training/objectives#binary')}">Binary cross-entropy →</a> Hardtanh replaces smooth saturation with clipping; quantization or bounded-state applications need their own accuracy and gradient checks.</p><div class="topic-scene" data-activation-lab><h3>Read the activation curve</h3><label>Function <select aria-label="Activation function">${activationNames.map(n=>`<option>${n}</option>`).join('')}</select></label><label>Input x<input type="range" min="-4" max="4" step="0.1" value="-1" aria-label="Activation input"></label><div data-body>${curve('ReLU',-1)}</div></div>${eq(String.raw`\operatorname{GELU}(x)\approx\frac x2\left[1+\tanh\left(\sqrt{\frac2\pi}(x+0.044715x^3)\right)\right]`,'The displayed approximation is distinct from exact xΦ(x).')}<p>Softmax couples several logits and normalizes them to a probability vector; it is not an independent scalar activation. Sparsemax and entmax use different geometries and matched losses; see <a href="${link('training/objectives')}">Losses and Objectives →</a>. No curve establishes a universally best activation or a universal variance guarantee.</p>`)}
${section('gates','From an activation to a gated feedforward layer',`${eq(String.raw`\begin{aligned}\operatorname{FFN}(x)&=W_{\rm down}\,\phi(W_{\rm up}x+b_{\rm up})+b_{\rm down}\\\operatorname{SwiGLU}(x)&=W_{\rm down}\big[(W_{\rm up}x)\odot\operatorname{SiLU}(W_{\rm gate}x)\big]\end{aligned}`,'Column-vector notation. Up and gate map d→m; down maps m→d. Biases are optional.')}<p>A gated linear unit (GLU) multiplies one linear branch by a sigmoid-transformed branch. SwiGLU changes that gate to SiLU. The gate scales values; it is not a sampled probability that a neuron fires. SwiGLU gates can be negative or exceed 1.</p><p>An ordinary two-projection FFN has about 2dm parameters. A three-projection gated FFN has about 3dm. Matching this parameter budget requires reducing gated m to about two-thirds of the ordinary m. Equal hidden ratios are not equal budgets.</p><p>MoE makes the feedforward transformation conditional on expert routing. It does not remove the gate or residual design choices. See <a href="${link('models/moe')}">Mixture of Experts →</a> for routing, balancing and expert layout.</p>`)}
${section('depth','A residual stream also mixes information across depth',`<p>The ordinary skip does more than help gradients. Its running sum gives every preceding update coefficient 1. Individual contributions can cancel. Once only the sum remains, a later layer cannot retrieve one contribution separately.</p>${eq(String.raw`\begin{aligned}h_\ell&=\sum_{i<\ell}v_i\quad\longrightarrow\quad\sum_{i<\ell}\alpha_{i\to\ell}v_i\\s_{i\to\ell}&=w_\ell^\top\operatorname{RMSNorm}(v_i),\qquad\alpha_{i\to\ell}=\operatorname{softmax}_i(s)\end{aligned}`,'Attention Residuals replaces uniform accumulation with a selective read over depth. v₀ is the embedding; subsequent vᵢ are sublayer outputs.')}<p>Each layer learns a pseudo-query w<sub>l</sub>. Its keys depend on the token's earlier states. Therefore a fixed learned query can still produce token-dependent weights. Keys are RMS-normalized for scoring; values remain the original source vectors.</p><p>Token attention chooses positions. Depth attention chooses earlier sublayer outputs. Full Attention Residuals (AttnRes, 2026) retains every source. For L sublayers and width d, depth retrieval adds O(L²d) arithmetic and O(Ld) history per token. Counting attention and MLP separately avoids a factor-of-two ambiguity.</p><p>The proposing team's target is Pre-Norm dilution. A convex depth mixture avoids an unbounded all-ones sum of fixed sources. The sources themselves can still grow. This is an architecture change, not a post-hoc patch for an existing checkpoint.</p>`)}
${section('depth-lab','Read a source, not just the accumulated sum',`<div class="topic-scene" data-depth-lab><h3>Four sources can cancel without being identical</h3><label>Query case<select aria-label="Depth query"><option>Uniform: [0,0]</option><option>Read positive x: [2,0]</option><option>Read positive y: [0,2]</option><option>Read negative x: [−2,0]</option><option>Read negative y: [0,−2]</option></select></label><div data-body>${depthBody(0)}</div></div><p>A zero pseudo-query initially produces uniform weights, not the ordinary unit-weight sum. Normalization changes the read's scale as well as its source preference. Key normalization reduces magnitude-based score domination; learned gains and source norms still need monitoring.</p>`)}
${section('block-attnres','Compress history into block summaries',`<p>Full history is costly to retain and communicate. Block AttnRes sums sublayer outputs within a block. A later layer attends to the embedding, completed block summaries and the current block's partial sum.</p>${eq(String.raw`\begin{aligned}b_n&=\sum_{j\in\mathcal B_n}f_j(h_j)\\h_\ell&=\operatorname{DepthAttention}(\text{embedding},\text{completed }b_n,\text{current partial sum})\end{aligned}`,'Compress writes within blocks; keep selective reads between blocks.')}<p>With N blocks of roughly ${m(String.raw`S=\frac LN`)} sublayers, history storage becomes ${m(String.raw`O(Nd)`)} per token. ${m(String.raw`N=L`)} approaches Full AttnRes. ${m(String.raw`N=1`)} retains the embedding separately and is close to ordinary accumulation, but is not identical to it.</p><p>A block boundary changes which sources are stored, not the meaning of an attention versus MLP operation. Compute a sublayer's read before updating its partial sum. At a boundary, append the finished summary once and begin a fresh partial sum. Do not count the same output in both sources.</p><p>The report's ablations find about eight blocks recover most Full AttnRes gains across its tested scales. A few distant summaries outperform retaining only nearby individual outputs in those comparisons. Block count is an empirical architecture/system choice, not a universal constant.</p>`)}
${section('attnres-systems','Make depth retrieval practical',`<p>Without recomputation, training already retains many activations. With recomputation or pipeline parallelism, additional history changes the storage and transfer pattern. The report caches summaries on physical pipeline ranks and transfers newly completed blocks rather than retransmitting the full history.</p><p>For P physical and V virtual stages, its peak transition transfer falls from O(PV) to O(P) chunks under that schedule. This is a transfer-count comparison, not a complete byte or latency model. Measured Block AttnRes training overhead is negligible without pipeline parallelism and under 4% with it on the reported stack.</p><p>At inference, fixed pseudo-queries permit a two-phase schedule. First batch all S queries against completed blocks. Then compute the sequential intra-block partial source and merge it with the precomputed result.</p>${eq(String.raw`\begin{aligned}m&=\max(m_a,m_b)\\\ell&=e^{m_a-m}\ell_a+e^{m_b-m}\ell_b\\o&=\frac{e^{m_a-m}\ell_a o_a+e^{m_b-m}\ell_b o_b}{\ell}\end{aligned}`,'Stable online-softmax merge for nonempty groups with finite maxima and ℓ>0. Each group stores maximum m, shifted mass ℓ and normalized value o. A masked empty group must be skipped; if both are empty, use an explicit masked-row policy rather than dividing by zero.')}<p>For ${m(String.raw`L=128, N=8, S=16`)}, estimated residual I/O per token per sublayer is ${m(String.raw`3d`)} elements for ordinary residuals, ${m(String.raw`5.5d`)} for Block AttnRes, ${m(String.raw`24d`)} for scheduled Full AttnRes and ${m(String.raw`34d`)} for four-stream mHC. These are residual-mechanism estimates, not whole-model traffic.</p><p>The report measures under 2% inference-latency overhead on its typical workloads. Long-context prefill adds ${m(String.raw`NTd`)} history elements: its 128K, eight-block example is about 15 GB before sharding. Sequence sharding across P devices reduces that cache to ${m(String.raw`N\frac TP d`)} elements per device, with integration into reduce-scatter/all-gather. See <a href="${link('training/parallelism')}">Distributed Training and Parallelism →</a>.</p>`)}
${section('attnres-evidence','What the Attention Residuals experiments establish',`<p>The proxy study uses MoE models with 194M–528M activated non-embedding parameters, 38.7B–119B tokens, 12–17 attention layers plus equally many MLP layers, and 8K context. Its fitted curves describe proxy training loss, not serving latency.</p>${eq(String.raw`\begin{aligned}L_{\mathrm{baseline}}&=1.891C^{-0.057}\\L_{\mathrm{Block}}&=1.870C^{-0.058}\\L_{\mathrm{Full}}&=1.865C^{-0.057}\end{aligned}`,"C&gt;0 is training compute in the report’s PFLOP/s-day units, not wall-clock days. The fits describe the stated proxy runs; extrapolation beyond them is not established.")}<p>At 5.6 PFLOP/s-days, the fitted Block loss is 1.692 versus baseline 1.714. The inferred 1.25× compute advantage is a curve comparison, not a universal wall-clock saving. At the largest proxy point, measured validation losses are baseline 1.719, Block 1.693 and Full 1.692.</p>${table('Ablations in the report’s 436M-active proxy setting; lower validation loss is better',['Method','Loss'],[['Pre-Norm','1.766'],['DenseFormer static mixing','1.767'],['mHC','1.747'],['Full AttnRes','1.737'],['Input-dependent query','1.731'],['Input-independent mixing','1.749'],['Sigmoid rather than softmax','1.741'],['Full without key RMSNorm','1.743'],['Block, size 4','1.746'],['Block, 16 heads','1.752'],['Block without key RMSNorm','1.750']])}<p>The input-dependent query improves this loss but requires a d×d projection and sequential reads. The simpler pseudo-query supports batched inference. The multi-head result suggests shared depth choices are useful in this setting; it does not prove channel-specific retrieval is never useful.</p><p>The larger controlled experiment is Kimi Linear: 48B total, 3B active parameters; 27 Transformer blocks counted as 54 sublayers; eight of 256 routed experts plus one shared expert. Six sublayers per AttnRes block produce nine block summaries plus the embedding. Training uses Muon, WSD, an 8M-token global batch, 1T pretraining tokens at 4K, about 400B high-quality mid-training tokens and context extension to 32K.</p>${table('Base-model downstream comparison; score changes are percentage points',['Benchmark','Baseline','Block AttnRes','Change'],[['MMLU','73.5','74.6','+1.1'],['MMLU-Pro','52.2','52.2','0.0'],['GPQA-Diamond','36.9','44.4','+7.5'],['BBH','76.3','78.0','+1.7'],['MATH','53.5','57.1','+3.6'],['HumanEval','59.1','62.2','+3.1'],['MBPP','72.0','73.9','+1.9'],['CMMLU','82.0','82.9','+0.9'],['C-Eval','79.6','82.5','+2.9']])}<p>The method matches or improves every listed score; MMLU-Pro ties. Larger reasoning/code gains are consistent with the team's compositional-retrieval hypothesis, not proof of that mechanism. This is not a controlled post-training or agent comparison.</p><p>Learned weights are mainly local, with long skips and persistent embedding reads. Attention sublayers use broader depth histories; MLP reads are more concentrated near recent sources. Some sources become depth-wise attention sinks. Block summaries may regularize as well as compress, but that causal interpretation remains a hypothesis.</p>${table('Residual mechanisms change different accessible-history rules',['Method','History','Weights'],[['Standard residual','One accumulated stream','Fixed unit additions'],['ReZero / LayerScale','One accumulated stream','Learned static branch scale'],['Highway','Recurrent stream','Input-dependent gate'],['Hyper-Connections / mHC','Multiple recurrent streams','Input-dependent mixing'],['DenseFormer','Earlier individual outputs','Static learned weights'],['Full AttnRes','Every individual output','Token-dependent softmax'],['Block AttnRes','Summaries and partial block','Token-dependent softmax']])}<p>The report interprets recurrent multi-stream mechanisms as structured depth mixers, unlike dense cross-layer access. Stronger residual baselines matter. No independent replication is established here. Its largest controlled model has 3B active parameters; fitted compute and custom-kernel overheads must not be generalized to larger or unoptimized deployments. Deeper/narrower proxy preferences also increase serial inference depth. ${cite('https://arxiv.org/pdf/2603.15031','Attention Residuals report')} · ${cite('https://github.com/MoonshotAI/Attention-Residuals','Implementation')}</p>`)}
${section('head','One state, many vocabulary decisions',`${eq(String.raw`\begin{aligned}z(c,x)&=h_c^\top w_x,&p(x\mid c)&=\operatorname{softmax}_x(z(c,x))\\H&\in\mathbb R^{N\times d},&W&\in\mathbb R^{V\times d},\quad Z=HW^\top\in\mathbb R^{N\times V}\end{aligned}`,'N contexts share one vocabulary matrix W. Logits are scores; probabilities require normalization.')}<p>Each token competes through its output embedding w. The context network can be deep and nonlinear. The final head still compresses every vocabulary comparison into d shared directions. Numerical stabilization subtracts each row's maximum before exponentiation; that preserves probabilities but does not increase expressivity.</p><p>The output softmax is distinct from attention's softmax. One selects vocabulary tokens, the other selects source positions. Cross-entropy measures prediction error against targets; see <a href="${link('training/objectives')}">Losses and Objectives →</a>.</p>`)}
${section('tying','Sharing embeddings changes the parameter budget',`<p>Input embeddings and an ordinary output matrix both have V×d parameters. Tying uses the same matrix for both. A tied head projects h against the rows used for token lookup; it does not skip the vocabulary projection.</p>${eq(String.raw`P_{\rm untied}=2Vd,\qquad P_{\rm tied}=Vd,\qquad \Delta P=Vd`,'Excludes biases, factorized embeddings and unequal input/output dimensions.')}<p>At V=50,000 and d=2,048, tying saves 102.4M parameters. That can be substantial in a small model. In a larger backbone, it is a smaller fraction of the budget.</p><p>Compare two distinct experiments. Keeping the backbone fixed isolates the extra freedom and extra parameters of untying. Keeping total parameters fixed requires reallocating width, depth or another part. Those comparisons answer different questions.</p><p>Tying can regularize or reduce quality in a particular setting. Untying can improve freedom without removing the output-rank limit. Large-model parameter fractions alone do not establish a quality benefit.</p>`)}
${section('rank','Why softmax cannot recover every distinction',`<p>A bias-free linear head factors logits through width d. Log normalization subtracts one scalar per context, so it adds at most one rank-one term.</p>${eq(String.raw`\begin{aligned}Z&=HW^\top,\qquad \operatorname{rank}(Z)\le d\\s_c&=\log\sum_x\exp(Z_{c,x})\\\log P&=Z-s\mathbf1^\top,\qquad\operatorname{rank}(\log P)\le d+1\end{aligned}`,"H: N×d context states; W: V×d output embeddings; s: N-vector. The bound concerns log probabilities, not the rank of P.")}<p>The sharper test removes these row constants. Choose a reference token r. The log-odds matrix ${m(String.raw`D_{c,x}=\log\frac{p(x\mid c)}{p(r\mid c)}`)} equals ${m(String.raw`h_c^\top(w_x-w_r)`)}. Its rank is at most d. The probability matrix P itself can have higher rank; that is not a contradiction.</p>${formulaTable('A positive target distribution from two contexts; token C is the reference. On narrow screens, scroll horizontally',['Context','p(A)','p(B)','p(C)','log A/C','log B/C'],[['1',m(String.raw`\dfrac12`),m(String.raw`\dfrac14`),m(String.raw`\dfrac14`),m(String.raw`\log 2`),'0'],['2',m(String.raw`\dfrac14`),m(String.raw`\dfrac12`),m(String.raw`\dfrac14`),'0',m(String.raw`\log 2`)]])}<p>This 2×2 log-odds matrix has determinant ${m(String.raw`(\log 2)^2`)} and rank 2. A bias-free ${m(String.raw`d=1`)} head cannot represent it. Increasing Transformer depth without increasing the final factorization width cannot repair that exact limitation.</p>${eq(String.raw`A=\log P^*,\quad\mathcal F(A)=\{A+\lambda\mathbf1^\top:\lambda\in\mathbb R^N\},\quad d\ge\min_{A'\in\mathcal F(A)}\operatorname{rank}(A')`,'Assumes strictly positive target probabilities and a bias-free linear head; sufficient representability also needs a context network capable of the required factorization.')}<p>A row shift changes rank by at most one. Thus ${m(String.raw`d<\operatorname{rank}(A)-1`)} is a sufficient obstruction. Output bias adds a shared vocabulary term of rank at most one. It changes these precise bounds; the two-context example above is deliberately bias-free.</p>`)}
${section('mixtures','Mix distributions after normalization',`<p>A mixture of contexts combines hidden states first: ${m(String.raw`h'=\sum_k\pi_k h_k`)}, then ${m(String.raw`\operatorname{softmax}(h'W^\top)`)}. This is still one d-dimensional state. A mixture of softmaxes (MoS) normalizes each component separately, then adds probability vectors.</p>${eq(String.raw`\begin{aligned}p_{\rm MoC}&=\operatorname{softmax}\!\left[\left(\sum_k\pi_k h_k\right)W^\top\right]\\p_{\rm MoS}&=\sum_k\pi_k\operatorname{softmax}(h_kW^\top),\quad\pi_k\ge0,\quad\sum_k\pi_k=1\end{aligned}`,'Only the second order escapes the original shared linear-softmax factorization. It does not guarantee useful high rank for every parameter choice.')}<div class="topic-scene" data-mixture-lab><h3>Two modes versus their averaged state</h3><label>Weight π on the negative component<input type="range" min="0" max="1" step="0.05" value="0.5" aria-label="Output mixture weight"></label><div data-body>${mixtureBody(.5)}</div></div>${table('Output modifications affect different limits',['Change','Effect'],[['More depth / MLP before same-width head','Improves context function; rank bound remains'],['Larger final output width','Raises factorization capacity'],['Untied embeddings','Adds parameter freedom; width bound remains'],['Output bias','Adds a rank-one vocabulary term'],['Mixture of contexts','Does not break the factorization'],['Mixture of softmaxes','Can express higher-rank log probabilities'],['Suitable nonlinear logits','Can change rank; analyze the actual function'],['Sampled softmax','Changes objective computation, not this head family'],['Hierarchical softmax','Changes factorization; no automatic higher-rank guarantee']])}<p>MoS is not MoE. A routed FFN changes how h is produced. MoS changes how the final distribution is formed. A model can use either, both or neither.</p>`)}
${section('head-evidence','Separate algebraic rank from useful probability error',`<p>Yang et al.'s ICLR 2018 work evaluates RNN language models, not contemporary large Transformers. On Penn Treebank with 10,000 tokens, reported empirical log-probability ranks are 400 for a width-400 softmax, 280 for width-280 MoC and 9,981 for width-280 MoS. Numerical rank depends on the threshold.</p><p>Additional components initially improve rank and likelihood, but can stop helping or overfit. The original settings report roughly 2–3× slower training with up to 15 components. These experiments establish a useful counterexample, not a recommendation that every LLM replace its head. ${cite('https://arxiv.org/html/1711.03953v2','Softmax bottleneck: theory and PTB evidence')}</p><p>High exact rank can be dominated by tiny singular values. The practical question is probability error in the discarded directions. The true language distribution's high rank is a hypothesis, not an observable theorem. Computing vocabulary logits can also be expensive; that computational bottleneck is separate from representational rank.</p><p>For a diagnostic, collect diverse contexts and a fixed token subset. Compute stable log probabilities, subtract one reference-token column, and inspect the singular-value spectrum. Report precision, threshold and matrix dimensions. Too few contexts or tokens cap measured rank. Better rank alone does not guarantee better cross-entropy.</p>`)}
${section('stop-gradient','A gradient boundary is not a teacher update',`${eq(String.raw`\begin{aligned}\operatorname{sg}(x)&=x,&\frac{\partial\operatorname{sg}(x)}{\partial x}&=0\\\mathcal L&=\|s-\operatorname{sg}(t)\|_2^2,&\frac{\partial\mathcal L}{\partial s}&=2(s-t),\quad\frac{\partial\mathcal L}{\partial t}=0\end{aligned}`,'Stop-gradient changes derivative paths without changing the target value.')}<p>A self-supervised matching loss can compare two augmented views of the same input. The student predicts the detached target representation. Detachment changes the backward path, not either view's forward value.</p><p>A detached target branch can still share parameters with the student. Gradients through the student path update those shared parameters. Detaching one tensor does not freeze every use of its weights.</p><p>An exponential moving average (EMA) teacher is a separate update rule.</p>${eq(String.raw`\theta_{\mathrm{teacher}}\leftarrow a\theta_{\mathrm{teacher}}+(1-a)\theta_{\mathrm{student}}`,"Apply this parameter update outside differentiation. Momentum a lies in [0,1]; a=1 leaves the teacher unchanged, while a=0 copies the student.")}<p> BYOL and DINO use momentum targets. SimSiam uses stop-gradient without a momentum teacher. Stop-gradient does not inherently require storing two parameter copies. ${cite('https://arxiv.org/abs/2011.10566','SimSiam')}</p><p>For a plain matching loss, a constant output can still minimize disagreement. Stop-gradient alone is not a general anti-collapse proof. Predictors, normalization, centering, variance objectives or negatives change the full system. <a href="${link('models/vision')}">Self-Supervised Vision Learning</a> connects DINO, BYOL, SimSiam, LeJEPA and variance regularization to their complete anti-collapse objectives.</p>`)}
${section('reversible','Reconstruct activations instead of storing every layer',`<p>Ordinary x+F(x) is not automatically invertible. Reversible blocks impose an additive coupling structure. Split channels into x₁,x₂, then update them in sequence. This Feistel-like additive coupling is a reversible data path, not an encryption scheme.</p>${eq(String.raw`\begin{aligned}y_1&=x_1+f(x_2),&y_2&=x_2+g(y_1)\\x_2&=y_2-g(y_1),&x_1&=y_1-f(x_2)\end{aligned}`,'Invert the second write first. f and g themselves need not be invertible.')} ${traceLab('reversible-lab','Forward writes and reverse reconstruction','Follow a scalar pair through the same equations used for channel vectors.',reversibleFrames,0,revBody,'All input/output roles are named; this sequence illustrates exact arithmetic, not floating-point error.')}
<p>Under the ideal reversible-stack assumptions, saved boundary activations can become O(1) in depth rather than O(L). Parameters, gradients, optimizer states, temporary branch activations and non-reversible boundaries still consume memory.</p><p>Backward reconstructs an input, recomputes the local forward and differentiates that local computation. Ordinary eager autograd may still retain the whole forward graph unless a custom backward/storage strategy is used. Reconstruction is not a gradient approximation in exact arithmetic.</p><p>The original RevNet operation count estimates 4N versus ordinary 3N: about 33% extra. With roughly equal GPU forward/backward costs, the paper discusses about 50% instead. Neither is a universal measured overhead. Checkpointing makes a related recomputation/storage tradeoff without requiring this architecture. ${cite('https://arxiv.org/html/1707.04585v1','RevNet: coupling and recomputation')}</p><p>Floating-point subtraction can accumulate reconstruction error. Recompute dropout with the same random state. Store or checkpoint non-reversible operations. Verify reconstructed values and parameter gradients against a stored-activation baseline before claiming memory savings.</p>`)}
${section('budget','Count the actual architecture',`<p>Use conventional attention geometry ${m(String.raw`d=hp`)}, with h query heads, ${m(String.raw`h_{\mathrm{kv}}`)} key/value heads and p head width. GQA usually requires h divisible by ${m(String.raw`h_{\mathrm{kv}}`)}. Some architectures use a different attention-inner width; the following formulas must then change.</p>${eq(String.raw`\begin{aligned}P_{\rm attn}&\approx2d^2\left(1+\frac{h_{\rm kv}}h\right)\\P_{\rm FFN}&\approx\begin{cases}2dm&\text{ordinary}\\3dm&\text{gated}\end{cases}\\P_{\rm total}&\approx L(P_{\rm attn}+P_{\rm FFN})+cVd,\quad c=\begin{cases}1&\text{tied}\\2&\text{untied}\end{cases}\\M_{\rm KV}&\approx2LBT\,h_{\rm kv}p\,b_{\rm elem}\end{aligned}`,'Biases, normalization, positional parameters and auxiliary heads are omitted. Cache assumes retained keys and values at all positions/layers; b_elem is bytes per stored element.')}<p>Depth scales this parameter estimate linearly. Width generally contributes quadratically when head geometry and FFN ratio scale with it. KV cache instead depends directly on key/value heads and context length. Local-window eviction changes cache only if the serving implementation actually evicts those states.</p>${formulaTable('Valid illustrative geometries, not optimal training recipes. On narrow screens, scroll horizontally',['d','Query heads','KV heads','p','Gated m'],[['2,048','16','4','128','~5,461'],['3,072','24','6','128','8,192'],['4,096','32','8','128','14,336'],['4,096','64','8','64','14,336']])}<p>A 4,096-wide model with 32 heads cannot use ${m(String.raw`p=64`)} under ${m(String.raw`d=hp`)}. For ${m(String.raw`p=64`)}, use 64 query heads or explicitly change attention-inner width. The 14,336 FFN width is ${m(String.raw`3.5d`)}: its gated cost is ${m(String.raw`10.5d^2`)}, not the ordinary ${m(String.raw`4d`)} FFN's ${m(String.raw`8d^2`)}.</p><p>Head sizes 64 or 128 and GQA ratios 2,4,8 are candidate configurations, not quality or hardware guarantees. Profile kernels and compare trained quality. Use a dense baseline before attributing benefits to sparse layouts, shared experts or dense/MoE interleaving.</p><p>Parameter count is not wall-clock cost. MoE has distinct total and active parameters; looped models can reuse parameters while increasing compute. MTP, multimodal frontends, state-space mixers and nonuniform layer widths change accounting. Do not force MLA, OpenELM or Mamba into these conventional formulas.</p><p>Match data, batch size, optimizer, token budget and evaluation when comparing shapes. Critical batch size and FP8 behavior require their own training analysis. A depth-before-width heuristic must be tested against serial latency and the residual mechanism, not treated as a universal allocation law.</p>`)}
${section('budget-design','Turn a budget into testable designs',`<p>Choose deployment memory, latency and context requirements first. Then choose width and depth together, validate head geometry, set KV sharing, and tune feedforward capacity. These are experiment axes, not an optimal recipe.</p>
${table('Design candidates and their failure checks',['Candidate','Why consider it?','What can invalidate it?'],[['Dense baseline','Simple always-on transformations','Compare trained quality and actual throughput before adding routing complexity'],['Long-context hybrid','Local layers reduce access cost; periodic global layers retain direct retrieval','A five-local/one-global cadence is a report example, not a universal ratio'],['Interleaved dense/MoE','Always-on transformations plus large conditional capacity','Communication, shared-expert choices, drop policy and router balance can dominate'],['Looped MoE','Reuse stored weights while changing selected experts across passes','Routing must actually vary; trained exit boundaries do not guarantee safe early stopping']])}
<p>Count unique parameters for storage, executed active parameters for arithmetic, and repeated passes for total compute. Dense interleaving can make shared experts less necessary in a tested design; it does not prove shared experts are useless. Dropless routing still needs a declared capacity and imbalance policy.</p>
<p>Loop boundaries can be candidates for early exit when training exposes those states to output objectives. Evaluate stopping quality and latency rather than assuming every reused block is output-ready. <a href="${link('models/recurrence#sparse')}">Recurrent and Looped Models →</a> · <a href="${link('models/moe')}">Routing and expert layout →</a></p>
<p>Increasing batch size beyond the useful critical regime can reduce returns. The critical regime depends on the data, loss and optimizer. Compare more steps, different data or architecture changes at matched compute. <a href="${link('training/optimization')}">Optimization →</a> · <a href="${link('training/scaling')}">Scaling Laws →</a></p>
<p>Measure widths, precision formats and kernel support on the actual stack. Nonuniform layer widths, latent-compression models, sparse multimodal frontends and state-space mixers require their own accounting. <a href="${link('training/numerics')}">Precision →</a> · <a href="${link('models/attention#connectivity')}">Local/global access →</a> · <a href="${link('execution/performance')}">Performance accounting →</a></p>`)}
${section('checks','Checks before scaling the model',`<p>Start with tensor contracts: residual additions must match shapes; heads must match the declared inner width; training targets must be shifted. Confirm causal masks with a future-token perturbation test.</p><p>Then measure hidden-state RMS, branch-output RMS and gradient RMS by depth. Change normalization placement and initialization together only with an explicit rationale. A bounded branch input is not proof of a bounded residual stream.</p><p>Check tied weight identity, vocabulary shape and parameter counts. Distinguish rank limitation from numerical softmax stability. For reversible execution, compare values and gradients and measure peak memory, not only the number of saved tensors.</p><p>Finally measure complete training and serving cost. A lower loss at matched FLOPs can lose its advantage through communication, memory traffic or deeper serial execution. Use the <a href="${link('training/parallelism')}">parallelism reader</a> to connect architecture to placement and communication.</p>`)}
${section('sources','Sources and connected notes',`<p>${cite('https://arxiv.org/abs/1502.03167','BatchNorm (2015)')} · ${cite('https://arxiv.org/abs/1607.06450','LayerNorm (2016)')} · ${cite('https://arxiv.org/abs/1910.07467','RMSNorm (2019)')} · ${cite('https://arxiv.org/pdf/2203.00555','DeepNorm (2022)')} · ${cite('https://arxiv.org/pdf/2603.15031','Attention Residuals (2026)')}</p><p>${cite('https://arxiv.org/abs/1711.03953','Softmax bottleneck (2017 / ICLR 2018)')} · ${cite('https://arxiv.org/abs/1902.08077','Monotonic nonlinear logits')} · ${cite('https://arxiv.org/abs/1805.10829','Sigsoftmax')} · ${cite('https://arxiv.org/abs/1707.04585','Reversible networks')} · ${cite('https://arxiv.org/abs/2011.10566','SimSiam')}</p><p>${cite('https://huggingface.co/spaces/HuggingFaceTB/smol-training-playbook','Smol training playbook')} · ${cite('https://kexue.fm/archives/8620','Initialization and parameterization')} · ${cite('https://kexue.fm/archives/8747','BERT’s 0.02 initialization')} · ${cite('https://kexue.fm/archives/8994','DeepNorm discussion')} · ${cite('https://kexue.fm/archives/9009','Pre-Norm versus Post-Norm')} · ${cite('https://kexue.fm/archives/10831','Tanh versus normalization')}</p><p>${cite("https://arxiv.org/abs/2603.15031","Attention Residuals")} · ${cite("https://arxiv.org/abs/2510.26692","Kimi Linear")}.</p>`)}
`);}
export function mountTransformers(scope=document){mountTopic(scope,transformersMeta.slug,article=>{const norm=article.querySelector('[data-norm-lab]'),offset=norm.querySelector('input');offset.addEventListener('input',()=>norm.querySelector('[data-body]').innerHTML=normBody(Number(offset.value)));const act=article.querySelector('[data-activation-lab]'),select=act.querySelector('select'),x=act.querySelector('input');const draw=()=>act.querySelector('[data-body]').innerHTML=curve(select.value,Number(x.value));select.addEventListener('change',draw);x.addEventListener('input',draw);const depth=article.querySelector('[data-depth-lab]'),query=depth.querySelector('select');query.addEventListener('change',()=>depth.querySelector('[data-body]').innerHTML=depthBody(query.selectedIndex));const mix=article.querySelector('[data-mixture-lab]'),pi=mix.querySelector('input');pi.addEventListener('input',()=>mix.querySelector('[data-body]').innerHTML=mixtureBody(Number(pi.value)));mountTrace(article,'reversible-lab',reversibleFrames,revBody);});}
transformersMeta.searchText=transformersReader(()=> '').replace(/<[^>]*>/g,' ');
